from taf.ul.ettf.decorator_library.search_order import LibrarySearchOrder
from taf.ul.ettf.scheduler.base_listeners import TestListener
from taf.ul.ettf.utils.provider import library_robot_instance


class DecoratorLibrary(TestListener):
    DECORATOR_LIBRARY_PATH = 'taf.ul.ettf.decorator_library'

    def __init__(self, *libraries_names):
        super(DecoratorLibrary, self).__init__()

        self._sub_libraries = []
        for library_name in libraries_names:
            self._sub_libraries.append(library_robot_instance(library_name))

    def start_suite(self, name, attributes):
        LibrarySearchOrder.set_library_search_order(self.DECORATOR_LIBRARY_PATH)

    def decorator_method(self, func):
        raise NotImplementedError('decorator_method has to be overridden')

    def get_keyword_names(self):
        names = []
        for lib in self._sub_libraries:
            for name in self._get_public_methods(lib):
                names.append(name)
        return names

    @staticmethod
    def _get_public_methods(lib):
        return [name for name in dir(lib) if not name.startswith('_')]

    def __getattr__(self, name):
        for lib in self._sub_libraries:
            if hasattr(lib, name):
                return self.decorator_method(getattr(lib, name))


decorator_library = DecoratorLibrary
